# Golden values for phn-epi trend.rs.
# Run: R_LIBS_USER=<lib with 'trend'> Rscript trend.R > ../trend.json
# APC: Poisson glm with log(population) offset, Wald interval (confint.default).
# Joinpoint segments: glm with the joinpoint fixed at the location our search
# must find (continuous hinge term). ITS: glm with level and slope terms.
# Mann-Kendall and Sen's slope: trend::mk.test, trend::sens.slope.
suppressPackageStartupMessages({library(jsonlite); library(trend); library(MASS)})
ctl <- glm.control(epsilon = 1e-12, maxit = 200)
year <- 2006:2025
pop <- round(60000 * 1.004^(0:19))
cases <- c(41, 44, 50, 49, 57, 61, 66, 64, 72, 77, 74, 70, 66, 69, 63, 60, 58, 55, 57, 52)
d <- data.frame(t = year - 2006, cases = cases, pop = pop)
m1 <- glm(cases ~ t + offset(log(pop)), family = poisson, data = d, control = ctl)
ci1 <- confint.default(m1)["t", ]
apc <- list(percent = 100 * (exp(coef(m1)["t"]) - 1), lower = 100 * (exp(ci1[1]) - 1),
            upper = 100 * (exp(ci1[2]) - 1), p = summary(m1)$coefficients["t", 4])
# Joinpoint at 2015 (t = 9).
d$h <- pmax(d$t - 9, 0)
m2 <- glm(cases ~ t + h + offset(log(pop)), family = poisson, data = d, control = ctl)
b <- coef(m2); V <- vcov(m2); z <- qnorm(0.975)
seg <- function(cv) { e <- sum(cv * b); se <- sqrt(drop(t(cv) %*% V %*% cv)); 100 * (exp(c(e, e - z * se, e + z * se)) - 1) }
w <- c(9, 10) / 19
jp <- list(joinpoint = 2015, seg1 = seg(c(0, 1, 0)), seg2 = seg(c(0, 1, 1)), aapc = seg(c(0, 1, w[2])))
mk <- mk.test(cases / pop); ss <- sens.slope(cases / pop)
# Interrupted series (monthly, intervention at month 24) with seasonality.
set.seed(11); tm <- 0:47
lam <- exp(log(80) + 0.004 * tm - 0.25 * (tm >= 24) - 0.01 * pmax(tm - 24, 0) + 0.15 * sin(2 * pi * tm / 12))
y <- rpois(48, lam)
time <- 2022 + tm / 12
di <- data.frame(t = time - 2022, lv = as.numeric(time >= 2024), sl = pmax(time - 2024, 0) * (time >= 2024),
                 s1 = sin(2 * pi * time), c1 = cos(2 * pi * time), y = y)
m3 <- glm(y ~ t + lv + sl + s1 + c1, family = poisson, data = di, control = ctl)
m3n <- glm(y ~ t + lv + sl, family = poisson, data = di, control = ctl)
ci3 <- confint.default(m3)
its <- list(time = time, y = y, level_ratio = unname(exp(coef(m3)["lv"])), level_lower = unname(exp(ci3["lv", 1])),
            level_upper = unname(exp(ci3["lv", 2])), level_p = summary(m3)$coefficients["lv", 4],
            slope_change_p = summary(m3)$coefficients["sl", 4],
            seasonal_chi2 = 2 * as.numeric(logLik(m3) - logLik(m3n)))
cat(toJSON(list(note = "Generated by tests/fixtures/generators/trend.R (R glm, trend::mk.test, trend::sens.slope).",
                r_version = R.version.string, trend_version = as.character(packageVersion("trend")),
                year = year, pop = pop, cases = cases, apc = lapply(apc, unname), joinpoint = jp,
                mk = list(s = unname(mk$estimates["S"]), var = unname(mk$estimates["varS"]),
                          z = unname(mk$statistic), p = mk$p.value, tau = unname(mk$estimates["tau"])),
                sens = unname(ss$estimates), its = its), auto_unbox = TRUE, digits = NA, pretty = TRUE))
